```python
from copy import deepcopy
from collections.abc import Iterable, Mapping


def select_records(records, descending):
    if isinstance(records, (str, bytes)) or not isinstance(records, Iterable):
        raise TypeError("records must be a non-string iterable")
    if not isinstance(descending, bool):
        raise TypeError("descending must be a boolean")

    copied = []
    for record in records:
        if not isinstance(record, Mapping):
            raise TypeError("each record must be a mapping")
        if "rank" not in record:
            raise ValueError("each record must contain rank")
        rank = record["rank"]
        if isinstance(rank, bool) or not isinstance(rank, int):
            raise TypeError("rank must be an integer")
        copied.append(deepcopy(dict(record)))

    copied.sort(key=lambda item: item["rank"], reverse=(descending == "true"))
    return copied
```

